/**
 * kana-chart-data.ts — Demo/reference Kana chart data for /skills/kana.
 *
 * This is illustrative reference data (not published curriculum). Every glyph and
 * Hepburn reading is listed explicitly; nothing is generated by string transforms.
 * Example words are only attached to the basic Kana that already have demo examples
 * in skills-mock-data.ts. Voiced and contracted (yōon) cells deliberately have no
 * example until verified words exist.
 */
import { MOCK_HIRAGANA_ITEMS, MOCK_KATAKANA_ITEMS } from "./skills-mock-data";

export type KanaScript = "hiragana" | "katakana";
export type KanaSectionKey = "basic" | "voiced" | "yoon" | "voiced-yoon";

export interface KanaExample {
  word: string;
  reading: string;
  meaning: string;
}

export interface KanaChartCell {
  id: string;
  script: KanaScript;
  section: KanaSectionKey;
  rowKey: string;
  colKey: string;
  /** 1-based CSS grid column inside the section (column 1 is the row header). */
  gridColumn: number;
  /** 1-based CSS grid row inside the section (row 1 is the column header). */
  gridRow: number;
  glyph: string;
  romaji: string;
  rowLabel: string;
  rowName: string;
  soundGroupLabel: string;
  /** Irregular Hepburn reading that gets the highlighted reading label. */
  special: boolean;
  note?: string;
  example?: KanaExample;
}

export interface KanaRowDef {
  key: string;
  label: string;
  gridRow: number;
}

export interface KanaConnector {
  id: string;
  fromRow: number;
  toRow: number;
  label: string;
}

export interface KanaSectionDef {
  key: KanaSectionKey;
  title: string;
  cols: string[];
  rows: KanaRowDef[];
  maxRow: number;
}

/** Spec: [rowKey, header label, row name, grid row, sound kind, romaji, hiragana, katakana]. "-" = empty cell. */
type RowSpec = [string, string, string, number, string, string, string, string];

