function toRowDef(spec: RowSpec): KanaRowDef {
  return { key: spec[0], label: spec[1], gridRow: spec[3] };
}

const EXAMPLES: Record<KanaScript, Map<string, KanaExample>> = {
  hiragana: new Map(
    MOCK_HIRAGANA_ITEMS.map((i) => [i.glyph, { word: i.exampleWord, reading: i.exampleReading, meaning: i.exampleMeaning }]),
  ),
  katakana: new Map(
    MOCK_KATAKANA_ITEMS.map((i) => [i.glyph, { word: i.exampleWord, reading: i.exampleReading, meaning: i.exampleMeaning }]),
  ),
};

function build(script: KanaScript): KanaChartCell[] {
  const sets: [KanaSectionKey, string[], RowSpec[]][] = [
    ["basic", BASIC_COLS, BASIC_ROWS],
    ["voiced", BASIC_COLS, VOICED_ROWS],
    ["yoon", YOON_COLS, YOON_ROWS],
    ["voiced-yoon", YOON_COLS, VOICED_YOON_ROWS],
  ];
  const cells: KanaChartCell[] = [];
  for (const [section, cols, rows] of sets) {
    for (const [rowKey, label, rowName, gridRow, soundGroupLabel, romajiRow, hiraRow, kataRow] of rows) {
      const romaji = romajiRow.split(" ");
      const glyphs = (script === "hiragana" ? hiraRow : kataRow).split(" ");
      cols.forEach((colKey, index) => {
        if (glyphs[index] === "-") return;
        const key = `${section}:${rowKey}:${colKey}`;
        cells.push({
          id: `${script}-${section}-${rowKey}-${colKey}`,
          script,
          section,
          rowKey,
          colKey,
          gridColumn: index + 2,
          gridRow,
          glyph: glyphs[index],
          romaji: romaji[index],
          rowLabel: label,
          rowName,
          soundGroupLabel,
          special: SPECIAL_CELLS.has(key),
          note: SPECIAL_NOTES[key],
          example: EXAMPLES[script].get(glyphs[index]),
        });
      });
    }
  }
  return cells;
}

export const KANA_CELLS: Record<KanaScript, KanaChartCell[]> = {
  hiragana: build("hiragana"),
  katakana: build("katakana"),
};

/** Script-independent key so the selection survives switching Hiragana ⇄ Katakana. */
export function cellPositionKey(cell: Pick<KanaChartCell, "section" | "rowKey" | "colKey">): string {
  return `${cell.section}:${cell.rowKey}:${cell.colKey}`;
}

export function findCell(script: KanaScript, positionKey: string | null): KanaChartCell | null {
  if (!positionKey) return null;
  return KANA_CELLS[script].find((c) => cellPositionKey(c) === positionKey) ?? null;
}
